// Normalizing and filtering potential tech internship items
const items = [];

// Handle input data from previous nodes
for (const item of $input.all()) {
  const data = item.json;

  // If array (e.g. RemoteOK)
  if (Array.isArray(data)) {
    for (const job of data.slice(1, 15)) { // skip metadata index 0
      if (job.position && (job.position.toLowerCase().includes('intern') || (job.tags && job.tags.includes('internship')))) {
        items.push({
          json: {
            raw_id: job.id || job.url,
            title: job.position,
            company: job.company,
            location: job.location || 'Remote',
            url: job.url || job.apply_url,
            description: (job.description || '').slice(0, 1500),
            source: 'RemoteOK'
          }
        });
      }
    }
  } else if (data.data && Array.isArray(data.data)) {
    // If wrapped in data array (e.g. Arbeitnow)
    for (const job of data.data.slice(0, 15)) {
      if (job.title && job.title.toLowerCase().includes('intern')) {
        items.push({
          json: {
            raw_id: job.slug || job.url,
            title: job.title,
            company: job.company_name,
            location: job.location || (job.remote ? 'Remote' : 'On-site'),
            url: job.url,
            description: (job.description || '').slice(0, 1500),
            source: 'Arbeitnow'
          }
        });
      }
    }
  }
}

// Return normalized items
return items.length > 0 ? items : [];

parameters.text:
=You are an AI career assistant analyzing internship opportunities for a software engineering student.
Analyze this job opportunity and extract structured data:

Job Title: {{ $json.title }}
Company: {{ $json.company }}
Location: {{ $json.location }}
URL: {{ $json.url }}
Description: {{ $json.description }}

Return strict JSON format with these exact fields:
{
  "is_tech": boolean (true if software/web/mobile/data/ai/cloud/devops/IT related, false otherwise),
  "is_internship": boolean (true if internship/fellowship/trainee),
  "company_name": string,
  "country": string (company country or specify Remote Worldwide),
  "work_type": string (Remote, On-site, or Hybrid),
  "compensation": string (e.g. "Paid", "Unpaid", "Competitive stipend", or "Not specified"),
  "key_tech_stack": list of strings,
  "brief_summary": string (2-3 punchy bullet points describing what the intern will do),
  "apply_link": string
}
Output ONLY valid JSON.

parameters.jsCode:
try {
  const responseText = $json.text || $json.response?.text || JSON.stringify($json);
  // Extract JSON from markdown code block if present
  const cleanJson = responseText.replace(/```json/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleanJson);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { error: e.message, raw: $json.text } }];
}

